import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
"uuid-generator":{title:"UUID Generator",sections:[
{heading:"What a UUID represents",text:["A UUID is a 128-bit identifier normally written as 32 hexadecimal digits separated by hyphens in an 8-4-4-4-12 pattern.","Its purpose is practical uniqueness across systems without requiring a central counter. A generated UUID should be treated as an identifier, not as encrypted data, a password, or proof that a record is authentic."]},
{heading:"Versions and the bits inside the value",text:["UUID versions encode different generation strategies.","Version 4 uses random bits, while time-ordered approaches such as UUIDv7 combine a timestamp with randomness so newly created identifiers tend to sort chronologically. Version and variant bits consume part of the 128-bit space, so the visible hexadecimal string is structured rather than an unrestricted random number."]},
{heading:"Collision probability",text:["With a properly generated random UUIDv4, accidental collisions are extraordinarily unlikely because the random portion contains about 122 bits.","The birthday effect means collision risk grows with the square of the number generated, but even very large application fleets remain far from a practical collision threshold when a cryptographically strong random source is used. Poor random-number generation is a more realistic risk than the mathematics of UUIDv4 itself."]},
{heading:"Where UUIDs work well",text:["UUIDs are useful for database primary keys, public resource identifiers, distributed event IDs, offline-created objects and synchronization between independent services.","They avoid coordinating a global sequence before an object can be created. They are also safer to expose than a simple sequential ID when you do not want users to infer how many records exist, although an unpredictable identifier is not an authorization control."]},
{heading:"Database and indexing tradeoffs",text:["Random UUIDs can fragment B-tree indexes because inserts arrive throughout the key space instead of at the end. That can increase page splits, index size and cache pressure compared with compact sequential integers.","Time-ordered UUID formats can improve locality. Storage also matters: a native 16-byte UUID/binary representation is more compact than storing the 36-character textual form."]},
{heading:"Security and privacy limits",text:["A UUID is not a secret. Anyone who receives it may copy or share it, and applications must still enforce authentication and authorization.","Time-based UUID formats may reveal creation timing, and some historical UUID variants can embed hardware-related information. Never assume that a difficult-to-guess URL alone protects sensitive data."]},
{heading:"Using generated UUIDs correctly",text:["Generate identifiers with a well-tested platform API or cryptographically secure implementation, store them in a type appropriate to the database, and keep formatting consistent across services.","Do not repeatedly regenerate an ID for the same logical object unless a new identity is intended. When importing data from multiple systems, preserve existing identifiers or define an explicit mapping so references remain stable."]},
]},
"font-size-calculator":{title:"Font Size Calculator",sections:[
{heading:"CSS font-size units",text:["Font size on the web can be expressed in px, rem, em, percentages and viewport-related units. Pixels are CSS reference pixels rather than guaranteed physical screen pixels.","rem is relative to the root element font size, while em is relative to the current element context and can compound through nested components. Choosing the unit changes how a design responds to user settings and surrounding typography."]},
{heading:"Converting px and rem",text:["A common conversion is rem = pixels / root font size. With a 16px root, 24px equals 1.5rem and 14px equals 0.875rem.","The reverse is pixels = rem × root font size. These conversions are only equivalent for a known root size; users or applications may change that base, which is one reason rem-based typography can scale more naturally."]},
{heading:"Responsive typography",text:["Responsive type should not be designed by multiplying every heading at each breakpoint.","A better system defines a readable minimum, a useful maximum and a controlled scale between them. CSS clamp() can combine rem and viewport units so type grows fluidly without becoming tiny on narrow screens or oversized on wide monitors."]},
{heading:"Readability is more than size",text:["Font family, x-height, weight, line height, line length, contrast and rendering all affect perceived readability.","Two fonts at 16px can look substantially different. Body copy usually needs more generous line height than large headings, and long lines often need either a narrower content measure or slightly larger type to remain comfortable."]},
{heading:"Accessibility considerations",text:["Users may zoom the page, enlarge text or override browser defaults. Typography built with relative units and flexible containers generally survives these changes better than rigid pixel layouts.","Avoid clipping text inside fixed-height controls, and test at increased zoom. A calculator conversion should therefore be treated as a starting value, not permission to lock the interface to one visual size."]},
{heading:"Building a type scale",text:["A type scale creates intentional relationships between captions, body text, subheadings and display headings. Modular ratios can help, but exact mathematical progression is not required.","Test the hierarchy in real components: navigation, forms, cards, tables and long articles may need different density. Consistent tokens such as --text-sm, --text-base and --text-xl are easier to maintain than scattered one-off values."]},
{heading:"Practical conversion checks",text:["After converting a design value, inspect it in the actual browser rather than judging the number alone. Confirm the root font size, inherited styles and media queries.","Check narrow and wide viewports, long translated strings and browser zoom. If an em value appears unexpectedly large, inspect its parent because em can inherit a scaled context; rem avoids that particular nesting effect."]},
]},
"caloric-needs-calculator":{title:"Caloric Needs Calculator",sections:[
{heading:"What daily calorie needs estimate",text:["Daily energy need is an estimate of the food energy required to support resting metabolism, normal body functions, digestion and physical activity while maintaining body weight.","It is not a fixed biological constant. Two people with the same age, sex, height and weight can have different real expenditure because body composition, spontaneous movement, training volume and metabolic adaptation differ."]},
{heading:"BMR and resting metabolism",text:["Most calorie calculators begin with a basal or resting metabolic equation based on age, sex, body weight and height.","Equations such as Mifflin-St Jeor estimate population averages rather than directly measuring oxygen consumption. The result is best interpreted as a starting estimate of resting demand, not the number of calories a person should necessarily eat each day."]},
{heading:"From BMR to TDEE",text:["Total daily energy expenditure is commonly estimated by multiplying resting needs by an activity factor.","This step can introduce more error than the BMR equation because labels such as sedentary, moderate and very active compress a wide range of real behavior. A desk worker who trains intensely five days per week and a person with an active occupation may not fit the same multiplier even if both select active."]},
{heading:"Weight-loss and weight-gain targets",text:["A calorie deficit tends to reduce body mass over time and a surplus tends to increase it, but the relationship is dynamic.","Water, glycogen, menstrual-cycle changes, sodium, bowel contents and training inflammation can move scale weight independently of fat. Large aggressive deficits may impair adherence, training and lean-mass retention, while unnecessarily large surpluses can increase fat gain."]},
{heading:"Protein, food quality and satiety",text:["Calorie quantity matters for energy balance, but food composition affects hunger, training recovery and nutrient adequacy.","Protein generally supports satiety and lean tissue, fiber-rich foods improve fullness and dietary quality, and dietary fat is needed for normal physiological functions. A calorie target should therefore be paired with an eating pattern that provides adequate protein, micronutrients and foods the person can sustain."]},
{heading:"How to calibrate the estimate",text:["Use the calculator as an initial target, then compare it with several weeks of consistent body-weight and intake data. Daily weigh-ins can be noisy, so weekly averages are more informative.","If weight is stable when the goal is loss or gain, adjust modestly rather than making a dramatic change from one day of data. Changes in activity should trigger a fresh review."]},
{heading:"Important limitations",text:["Pregnancy, breastfeeding, childhood, eating disorders, significant illness, medications and high-level athletic training can require individualized nutrition guidance.","Energy equations also become less reliable at body-composition extremes. The calculator does not diagnose metabolic conditions and cannot know actual absorption or expenditure; persistent unexplained weight change deserves professional evaluation."]},
{heading:"Body composition and energy needs",text:["Two people at the same body weight can have different resting expenditure because lean tissue and organ mass contribute differently to metabolism.","Standard equations usually do not know precise body composition, so muscular athletes or people at body-composition extremes may see larger error. Direct or indirect calorimetry can provide a more individualized measurement when precision is clinically or professionally important."]},
{heading:"Thermic effect and activity components",text:["Total expenditure is often described as resting metabolism plus the thermic effect of food, structured exercise and non-exercise activity thermogenesis.","NEAT includes walking, standing, fidgeting and routine movement and can vary substantially between people or decline during dieting. This is one reason a fixed activity multiplier can drift away from reality over time."]},
{heading:"Adaptive responses during dieting",text:["As body mass falls, a smaller body usually requires less energy to maintain, and spontaneous activity may also change. Hunger can increase while training performance declines.","A deficit that produced steady loss at the beginning may later produce a smaller rate. Recalculate using current body weight and observed trends rather than treating the original target as permanent."]},
{heading:"Worked maintenance example",text:["Consider an adult whose estimated resting need is 1,600 kcal/day. An activity multiplier of 1.5 gives an initial TDEE estimate near 2,400 kcal/day.","This is not proof that maintenance is exactly 2,400. If several weeks of accurately tracked intake near 2,400 coincide with stable average body weight, the observed data provides stronger personal calibration than the equation alone."]},
{heading:"Rate of change and expectations",text:["A moderate target is usually easier to sustain than chasing the fastest possible scale change.","Early weight loss can be accelerated by glycogen and water changes, while later weeks may appear slower. Evaluate trends over multiple weeks and use waist, performance or other relevant measures where appropriate instead of reacting to every daily fluctuation."]},
{heading:"Exercise calories",text:["Wearables and cardio machines can provide useful consistency but may over- or underestimate calories burned.","Automatically eating back every displayed exercise calorie can erase an intended deficit if the estimate is high. When activity is already represented by the chosen activity factor, adding the same exercise expenditure again can also double-count it."]},
]},
"pe-ratio-calculator":{title:"P/E Ratio Calculator",sections:[
{heading:"The P/E formula",text:["Price-to-earnings ratio equals share price divided by earnings per share.","The same relationship can be calculated using total market capitalization divided by total net income attributable to common shareholders when definitions are aligned. A P/E of 20 means investors are paying about twenty dollars of market value for each dollar of the earnings measure used; it does not mean the investment will take exactly twenty years to repay itself."]},
{heading:"Trailing versus forward earnings",text:["Trailing P/E normally uses earnings from the last twelve months, while forward P/E uses analyst or company forecasts. Trailing data is historical and observable but can be stale after a major business change.","Forward earnings may better reflect expected operations but introduce forecast risk. Always label which earnings period is used because the two ratios can differ substantially."]},
{heading:"Why low is not automatically cheap",text:["A low P/E can indicate undervaluation, but it can also reflect falling earnings quality, heavy debt, cyclicality, litigation, disruption or expectations of decline.","A high P/E can reflect optimistic growth expectations, unusually strong economics or simple overvaluation. The ratio becomes useful when interpreted with business quality and future cash-generation assumptions rather than as a stand-alone ranking."]},
{heading:"Negative and near-zero earnings",text:["P/E loses meaning when earnings are negative because dividing price by a loss produces a negative number that is not economically comparable with a normal positive P/E.","Near-zero positive earnings can create extremely large ratios. In those cases investors may examine revenue, normalized earnings, free cash flow or enterprise-value metrics while recognizing that each alternative measures something different."]},
{heading:"Cyclical and one-time effects",text:["Commodity producers, banks, manufacturers and other cyclical businesses can look cheapest near peak earnings and most expensive near trough earnings.","One-time gains, restructuring charges, asset impairments and tax items can also distort reported EPS. Normalized earnings across a business cycle may provide better context, but normalization itself requires judgment and should be transparent."]},
{heading:"Comparing companies",text:["P/E comparisons are most meaningful among businesses with similar growth, capital intensity, accounting, risk and balance-sheet characteristics.","Comparing a mature utility directly with a rapidly growing software company can be misleading. Debt also matters because P/E is an equity metric; two companies with the same P/E may have very different financial leverage."]},
{heading:"Using P/E in valuation",text:["P/E can be connected to an earnings-yield view by taking E/P, the inverse of the ratio. It can also be compared with a company’s historical range, peer group and expected earnings growth.","None of these creates an intrinsic value automatically. A sensible analysis asks what growth, margins, reinvestment and risk would justify the multiple and what happens if those expectations are not achieved."]},
{heading:"Sector and accounting context",text:["Banks, insurers, REITs and asset-heavy industrial companies often require sector-specific interpretation because earnings and balance-sheet economics differ.","REIT investors may emphasize FFO/AFFO, while banks are sensitive to credit costs and book value. A P/E comparison is strongest when the denominator has similar accounting meaning across the companies being compared."]},
{heading:"EPS quality",text:["Earnings per share can be basic or diluted. Diluted EPS incorporates potential shares from options, convertibles and other instruments when applicable, so it often provides a more conservative denominator.","Share repurchases can also increase EPS even if total company profit is flat. When comparing P/E over time, inspect whether changes came from operating earnings or from the share count."]},
{heading:"Growth and the PEG idea",text:["Investors sometimes compare P/E with expected earnings growth through a PEG ratio, but this does not make growth forecasts reliable or make companies with the same PEG equally attractive.","Growth duration, return on invested capital and required reinvestment matter. A company growing 20% for two years is different from one that can compound at that rate for a decade."]},
{heading:"Interest rates and valuation multiples",text:["Valuation multiples often respond to required returns.","When risk-free yields rise, investors may demand a higher earnings yield, which can pressure P/E multiples even if company earnings do not immediately change. The relationship is not mechanical because growth expectations, risk premiums and sector conditions move at the same time."]},
{heading:"Worked interpretation example",text:["If a stock trades at $60 and trailing diluted EPS is $3, trailing P/E is 20. If analysts expect $4 EPS next year, forward P/E is 15.","That gap may reflect expected growth, but the forward figure only becomes real if the forecast is achieved. If next-year EPS reaches only $3.20, the valuation at the same $60 price would be 18.75 times rather than 15."]},
{heading:"P/E and free cash flow",text:["Accounting earnings include non-cash charges, accruals and capitalization rules, so profit can differ from cash generated for owners. Compare earnings with operating cash flow, capital expenditures and free cash flow.","Persistent divergence deserves investigation. P/E remains useful, but cash-flow context can reveal whether reported earnings are supported by cash economics."]},
]},
"flex-generator":{title:"Flexbox Generator",sections:[
{heading:"Flex container fundamentals",text:["display:flex turns an element into a flex formatting context and makes its direct children flex items.","The main axis is controlled by flex-direction, while the cross axis runs perpendicular to it. Many confusing Flexbox bugs come from thinking in screen directions such as horizontal and vertical instead of first identifying the current main and cross axes."]},
{heading:"justify-content and align-items",text:["justify-content distributes free space along the main axis; align-items controls how items align across the cross axis. With flex-direction:row, justify-content usually affects horizontal placement and align-items affects vertical placement.","Change the direction to column and those intuitive directions swap. align-self can override cross-axis alignment for one item."]},
{heading:"Sizing with flex-grow, shrink and basis",text:["The flex shorthand combines grow, shrink and basis. flex-basis establishes an initial main-size basis before remaining or missing space is distributed.","flex-grow controls how positive free space is shared, and flex-shrink controls how items contract when they do not fit. flex:1 commonly means items share available space, but intrinsic minimum sizes can still prevent expected shrinking."]},
{heading:"Wrapping and gaps",text:["flex-wrap allows items to move onto additional flex lines rather than continually shrinking.","gap creates consistent spacing between items without requiring margin tricks or special first/last-child rules. Each wrapped line is laid out independently, so Flexbox is not a substitute for two-dimensional grid alignment when columns across multiple rows must line up."]},
{heading:"Common overflow problems",text:["Text, images and nested controls can make a flex item refuse to shrink because its automatic minimum size is based on content.","min-width:0 is a common fix when long text should truncate or wrap inside a flexible child. Similarly, images should usually have responsive max-width behavior rather than forcing the container wider than the viewport."]},
{heading:"Flexbox versus Grid",text:["Flexbox is strongest for one-dimensional layout: navigation bars, button groups, card internals, toolbars and rows whose item sizes respond to content.","CSS Grid is generally clearer for explicit rows and columns or page-level two-dimensional arrangements. Many robust interfaces use Grid for the outer structure and Flexbox inside individual components."]},
{heading:"Using generated CSS",text:["Treat generated declarations as a readable starting point. Copy them into a semantic class or component style rather than relying on unexplained inline rules.","Test with extra-long labels, missing items, translated content, keyboard focus, narrow screens and zoom. The visually correct arrangement with three sample boxes may fail once real content changes intrinsic sizes."]},
]},
"roth-conversion-calculator":{title:"Roth Conversion Calculator",sections:[
{heading:"What a Roth conversion does",text:["A Roth conversion moves money from a pre-tax traditional IRA or eligible retirement account into a Roth account.","The converted taxable amount is generally included in ordinary income for that tax year. The tradeoff is paying tax now in exchange for future qualified Roth withdrawals that can be tax-free, subject to the applicable Roth rules."]},
{heading:"Marginal tax rate matters",text:["The relevant conversion cost is not simply current taxable income multiplied by one headline tax bracket. A conversion stacks on top of other income and can cross multiple brackets.","It can also interact with deductions, credits and state income taxes. Modeling conversions in layers helps show how much of the conversion falls into each marginal range."]},
{heading:"Future tax-rate comparison",text:["A conversion is more attractive when the marginal tax rate paid today is lower than the rate that would otherwise apply to future withdrawals, but the comparison is uncertain.","Future tax law, income, filing status and state residency may change. The analysis should compare realistic lifetime tax scenarios rather than assuming today’s bracket lasts forever."]},
{heading:"RMDs and retirement income",text:["Reducing pre-tax balances can reduce future required minimum distributions under rules applicable at the time, potentially lowering taxable retirement income.","That may also affect taxation of Social Security and Medicare income-related premiums. These interactions are complex and year-specific, so a simple calculator should present them as planning considerations rather than guaranteed savings."]},
{heading:"Paying the conversion tax",text:["Using cash outside the retirement account to pay conversion tax generally leaves more money inside the Roth to compound.","Withholding tax from the converted retirement balance reduces the amount invested and, depending on age and circumstances, can create additional tax or penalty issues. Liquidity for the tax bill is therefore an important part of conversion sizing."]},
{heading:"Five-year rules and access",text:["Roth IRAs have multiple five-year concepts, including rules related to qualified earnings and converted amounts.","Conversion access can be especially important for people planning withdrawals before traditional retirement age. The exact consequences depend on age, account history and withdrawal ordering, so the calculator should not imply that every converted dollar is immediately penalty-free."]},
{heading:"Partial conversions and annual planning",text:["Conversions do not need to be all-or-nothing. Many plans use partial annual conversions to fill a chosen tax bracket during lower-income years, such as between retirement and the start of large pensions, Social Security or RMDs.","Recalculate each year because investment values, income, deductions and tax thresholds change. Coordinate large conversions with a qualified tax professional when consequences are material."]},
{heading:"State tax planning",text:["State income-tax treatment can materially change conversion economics.","Someone expecting to move from a high-tax state to a no-income-tax state may prefer to delay some conversions, while the reverse move can strengthen the case for converting earlier. Residency rules and retirement-income exclusions vary, so use the state rules applicable to the conversion year and expected withdrawal years."]},
{heading:"Pro-rata rule and after-tax basis",text:["If a traditional IRA contains nondeductible after-tax basis as well as pre-tax money, a conversion is not necessarily allowed to cherry-pick only the after-tax dollars. The pro-rata calculation generally looks across relevant traditional, SEP and SIMPLE IRA balances under U.S.","rules. Track Form 8606 basis carefully so the same dollars are not taxed twice."]},
{heading:"Medicare and other income interactions",text:["A large conversion increases modified adjusted gross income and can affect Medicare income-related premiums in later years because IRMAA uses a lookback.","Higher income can also change the taxation of Social Security and eligibility for income-based credits or deductions. These indirect costs may make a conversion near a threshold more expensive than the federal bracket alone suggests."]},
{heading:"Conversion timing and market movement",text:["Converting after a market decline moves more shares for the same taxable dollar amount if the investor still wants the asset exposure, which can increase the amount of future recovery occurring inside Roth.","But markets are unpredictable, and current law generally does not allow simply undoing an IRA conversion through recharacterization. Do not base the entire strategy on predicting short-term prices."]},
{heading:"Estate-planning considerations",text:["Roth assets can be valuable for heirs because the original owner generally avoids lifetime RMDs from a Roth IRA, while beneficiaries face their own distribution rules.","Whether conversion improves an estate depends on the owner’s tax rate, heirs’ expected rates, spending needs and the time assets can remain invested. Paying tax early is not automatically beneficial merely because the account becomes Roth."]},
{heading:"Worked bracket-filling concept",text:["Suppose taxable income before conversion leaves $30,000 of room in a chosen marginal bracket.","A planner might model a $30,000 conversion, then separately test $20,000 and $40,000 because deductions and thresholds can shift. The objective is not to fill a bracket at any cost; it is to compare the lifetime tax effect while preserving enough cash for taxes and near-term spending."]},
]},
"crypto-profit-calculator":{title:"Crypto Profit Calculator",sections:[
{heading:"Core profit calculation",text:["A basic crypto trade profit starts with the quantity acquired, purchase price and sale price. Gross profit equals sale proceeds minus acquisition cost.","Percentage return is profit divided by cost basis, not divided by sale proceeds. When multiple purchases occur at different prices, the result depends on which units are treated as sold and how the applicable tax rules determine basis."]},
{heading:"Trading fees and spreads",text:["Exchange fees, network fees and bid-ask spread can materially reduce a trade’s economic return, especially for frequent or small transactions.","A calculator that compares only quoted buy and sell prices overstates net profit when these costs are omitted. Include purchase fees in basis where appropriate and subtract disposal costs from proceeds when modeling the trade."]},
{heading:"Cost basis across multiple lots",text:["Dollar-cost averaging creates separate acquisition lots at different prices and dates.","Average entry price can summarize the position economically, but tax reporting may require specific-lot, FIFO or another permitted basis method depending on jurisdiction and records. Keep transaction-level history rather than relying solely on the wallet’s current balance."]},
{heading:"Taxes and holding period",text:["Crypto disposals can create taxable gains or losses, and exchanging one token for another may itself be a disposal in many tax systems. Short- and long-term treatment, loss rules and reporting requirements depend on jurisdiction.","The calculator’s pre-tax profit should not be mistaken for spendable after-tax profit. Preserve timestamps, fiat values and fees for each transaction."]},
{heading:"Volatility and leverage",text:["Crypto prices can move sharply in both directions, so a historical profit calculation does not estimate future return.","Leverage adds liquidation and financing risk: a position can be closed before the underlying asset has a chance to recover. Profit scenarios should separate unleveraged spot holdings from margin, futures or perpetual contracts because their cash flows and risks differ."]},
{heading:"Stablecoins, staking and rewards",text:["Returns may include more than price appreciation. Staking rewards, lending yield, airdrops and token incentives can affect total return and may create income-tax consequences when received.","Stablecoins can also depeg and carry issuer, reserve, smart-contract or platform risk. Do not label yield as risk-free merely because the token targets a stable fiat value."]},
{heading:"Reading the result responsibly",text:["Use the result to reconcile what happened to a defined set of transactions: invested amount, proceeds, fees and realized gain or loss.","Do not extrapolate one winning percentage into an annual forecast without considering volatility and path dependency. For material holdings, verify the calculation against exchange exports, wallet records and tax-lot software before filing or making a major decision."]},
{heading:"Break-even sale price",text:["Break-even is the sale price at which proceeds after disposal costs equal the acquisition basis including purchase costs.","If fees are percentage-based, simply selling at the original quoted purchase price can still produce a loss. Calculating a fee-adjusted break-even price is especially useful for short-term traders because a small favorable market move may be consumed entirely by entry and exit costs."]},
{heading:"Worked trade example",text:["Suppose 0.5 BTC is purchased at $40,000 per coin. The asset cost is $20,000 before fees.","If it is later sold at $52,000 per coin, gross proceeds are $26,000 and gross price profit is $6,000. If the buy and sell each incur 0.5% trading costs, the economic profit is lower. Writing each leg separately prevents the common mistake of applying a percentage return to the wrong base."]},
{heading:"Unrealized versus realized gains",text:["A position can show a large unrealized gain while it remains held, but that is not the same as realized profit.","Realization normally occurs when units are sold, exchanged or otherwise disposed of under the relevant rules. Portfolio dashboards may combine realized and unrealized performance, so reconcile the calculator to a clearly defined period and set of transactions."]},
{heading:"Portfolio return versus one token",text:["A token can rise while the overall portfolio falls if position sizes differ or other assets decline.","Measure portfolio performance using beginning value, external contributions and withdrawals rather than averaging token percentage returns. For active traders, time-weighted and money-weighted return answer different questions and can diverge when deposits occur around large price moves."]},
{heading:"Record keeping and reconciliation",text:["Wallet transfers between accounts you control are economically different from purchases or sales, but exchange exports can make them look similar without context.","Match transaction IDs, timestamps, quantities and network fees so transfers are not accidentally counted as disposals twice. Reconcile ending quantities to wallets after calculating profit; unexplained quantity differences usually indicate missing transactions, rewards or fees."]},
{heading:"Risk beyond price",text:["Custody, private-key loss, exchange insolvency, smart-contract exploits, bridge failures and regulatory restrictions can cause losses that a price-profit formula does not capture.","Diversifying exchanges does not remove asset volatility, and self-custody trades platform risk for operational responsibility. Keep these risks separate from the arithmetic return so a positive backtest is not mistaken for a complete investment case."]},
]},
"cron-expression":{title:"Cron Expression",sections:[
{heading:"The five-field cron model",text:["Traditional Unix cron uses five scheduling fields: minute, hour, day of month, month and day of week.","A value can be a number, wildcard, range, list or step depending on the implementation. Some platforms add a seconds field or use a six/seven-field syntax, so an expression copied between systems may not mean the same thing."]},
{heading:"Wildcards, ranges, lists and steps",text:["An asterisk means every permitted value in a field. Hyphens define ranges, commas define lists and slash syntax defines steps such as every 15 minutes.","Expressions should be read field by field rather than as natural-language prose. A small syntax change can turn a once-daily job into one that executes many times per hour."]},
{heading:"Day-of-month versus day-of-week",text:["Cron implementations differ in how day-of-month and day-of-week interact when both are restricted. Classic cron commonly runs when either field matches, which surprises users expecting an AND condition.","Cloud schedulers and libraries may define different semantics. Verify the target scheduler’s documentation before using expressions for billing, backups or other critical automation."]},
{heading:"Time zones and daylight saving",text:["Cron schedules run in a time zone determined by the operating system, container, scheduler or explicit configuration.","Daylight-saving transitions can cause a local clock time to occur twice or not at all. For globally coordinated jobs, UTC often reduces ambiguity; for business workflows tied to local time, DST behavior must be intentionally tested."]},
{heading:"Missed jobs and downtime",text:["Traditional cron generally does not replay jobs that were missed while a machine was powered off.","Other schedulers may provide catch-up or misfire policies. If execution is essential, use a scheduler with persistence, retries and monitoring rather than assuming the expression itself guarantees delivery."]},
{heading:"Concurrency and idempotency",text:["A schedule says when a job is eligible to start; it does not ensure the previous run has finished.","Long-running tasks can overlap and process the same data twice. Use locks, idempotency keys or scheduler-level concurrency controls where duplicate execution could cause harm."]},
{heading:"Testing an expression",text:["Before deployment, enumerate the next several run times and compare them with the intended calendar behavior, including month boundaries and DST transitions.","Log start/end status, alert on failures and make the job safe to retry. Human-readable comments next to complex cron expressions reduce maintenance errors when another developer changes the schedule later."]},
]},
"emergency-fund-calculator":{title:"Emergency Fund Calculator",sections:[
{heading:"What an emergency fund is for",text:["An emergency fund is liquid money reserved for unplanned financial shocks such as job loss, urgent travel, essential repairs or insurance deductibles.","It is different from money earmarked for predictable annual expenses. The target should therefore be based on essential obligations and the household’s risk profile, not simply a generic multiple of total spending."]},
{heading:"Months of essential expenses",text:["A common framework multiplies essential monthly expenses by a chosen number of months.","Essential expenses may include housing, utilities, groceries, insurance, minimum debt payments, transportation and necessary healthcare. Discretionary spending that could be cut during an emergency does not necessarily need full replacement, although every household defines necessities differently."]},
{heading:"Choosing the number of months",text:["Three to six months is a familiar rule of thumb, but income stability matters.","A household with two stable independent incomes may need less buffer than a single-income freelancer with volatile contracts. Dependents, health risks, specialized employment, high insurance deductibles and limited family support can justify a larger reserve."]},
{heading:"Where to keep the money",text:["Emergency savings prioritizes access and capital stability over maximum long-term return.","Insured savings accounts, money-market deposit accounts or similar liquid vehicles are common choices. Investing the entire reserve in volatile assets can force a sale during a market decline, precisely when a job loss or other emergency may also occur."]},
{heading:"Debt versus emergency savings",text:["High-interest debt creates a competing use for cash, but reducing the emergency fund to zero can cause the next unexpected bill to go straight back onto expensive credit.","A staged approach can build a starter reserve, attack costly debt and then expand the fund. The right sequence depends on interest rates, job stability and access to backup liquidity."]},
{heading:"Replenishment and inflation",text:["After using the fund, create a replenishment plan rather than treating the target as permanently complete.","Essential expenses also rise over time, so recalculate after rent changes, a move, marriage, children, new debt or major insurance changes. A target based on expenses from several years ago may no longer cover the intended number of months."]},
{heading:"What the calculator cannot predict",text:["No calculator knows the size or timing of the next emergency.","The output is a planning reserve, not a guarantee against financial hardship. Separate emergency savings from sinking funds for known costs such as annual insurance premiums, holidays or planned vehicle replacement; combining them can make the emergency balance look larger than the truly available cushion."]},
{heading:"Worked target example",text:["If essential monthly expenses are $3,200, a three-month reserve is $9,600 and a six-month reserve is $19,200.","A worker in a stable dual-income household might choose the lower end, while a sole earner in a specialized cyclical industry might prefer the higher end or more. The multiplication is easy; selecting the appropriate months is the real planning judgment."]},
{heading:"Insurance deductibles and concentrated risks",text:["Review the largest amount you might need quickly for health, home and auto deductibles.","Homeowners in disaster-prone areas may face exclusions or separate deductibles, while renters may have fewer property-repair obligations. An emergency fund should complement insurance, not replace coverage for losses that would overwhelm savings."]},
{heading:"Access time matters",text:["Money can be technically liquid but still inconvenient during a weekend, bank outage or transfer delay.","Keep at least part of the reserve where it can be accessed quickly without market-sale settlement or penalties. At the same time, avoid keeping excessive physical cash where theft, loss and lack of deposit insurance create different risks."]},
{heading:"Job-loss planning",text:["Estimate how quickly unemployment benefits, severance or a partner’s income would begin and how much of essential spending they would cover.","A six-month expense target may fund much longer than six months if partial income continues, or less if health-insurance premiums rise after job loss. Modeling the actual gap gives a more useful target than months alone."]},
{heading:"Building the fund",text:["If the target feels large, automate a fixed transfer on payday and direct windfalls or bonuses toward milestones such as one month, three months and the final target.","Keep the reserve separate enough that routine spending does not consume it, but visible enough to monitor. Once fully funded, redirect the regular contribution to the next priority while reviewing the target periodically."]},
]},
"xml-formatter":{title:"XML Formatter",sections:[
{heading:"Well-formed XML",text:["An XML formatter can only reliably pretty-print a document that follows XML syntax: one document element, properly nested tags, quoted attribute values and correctly escaped reserved characters.","Formatting does not repair semantic mistakes automatically. A file can be perfectly well-formed XML while still violating the schema expected by the application that consumes it."]},
{heading:"Elements, attributes and text",text:["XML represents information through elements, attributes and text nodes.","Whitespace between elements is often insignificant, but whitespace inside text content can be meaningful to an application. A formatter should therefore be careful with mixed-content documents where text and child elements are interleaved; inserting line breaks can alter the intended textual value."]},
{heading:"Namespaces",text:["Namespace prefixes distinguish vocabularies that use the same local element names.","The prefix itself is shorthand for a namespace URI and can change without changing the expanded name. When debugging XML, inspect namespace declarations rather than assuming <a:item> and <b:item> are equivalent or different based only on the visible prefix."]},
{heading:"Entities and escaping",text:["The characters &, < and certain quote contexts require escaping.","Standard entities such as &amp; and &lt; allow reserved characters to appear as data. External entities and DTD processing can introduce security risks in parsers, including XXE attacks, so server-side applications should use hardened parser settings when accepting untrusted XML."]},
{heading:"Declarations and encoding",text:["An XML declaration can specify a character encoding such as UTF-8.","The declared encoding must agree with the actual bytes supplied to the parser. Copying text through systems that silently change encoding can produce confusing errors even when the visible characters look normal."]},
{heading:"Pretty printing versus canonicalization",text:["Pretty printing adds indentation and line breaks for human readability.","Canonical XML is a different process designed to produce a standardized byte representation for comparisons or digital signatures. Never pretty-print signed XML and assume the signature will remain valid; changing whitespace or serialization can change the signed byte stream."]},
{heading:"Validation and production use",text:["After formatting, validate against XSD, Relax NG or application-specific rules when a schema exists.","Large XML documents may require streaming parsers rather than loading the entire tree into memory. Treat a browser formatter as a development aid: sensitive production payloads should not be pasted into third-party services unless their privacy and retention behavior is acceptable."]},
]},
"css-unit-converter":{title:"CSS Unit Converter",sections:[
{heading:"Absolute and relative CSS units",text:["CSS supports px as a reference pixel and relative units such as rem, em, %, vw, vh, vmin and vmax.","Newer viewport units account for dynamic browser UI on mobile. The numerical conversion between units is only exact when the reference context is known; 1rem cannot be converted to one universal pixel value if the root font size is unknown."]},
{heading:"rem and em",text:["rem resolves against the root element’s font size, making it useful for consistent spacing and typography tokens. em resolves against the relevant font-size context and can compound through nesting.","For properties other than font-size, em commonly refers to the element’s computed font size. This makes em powerful for components that should scale internally with their text."]},
{heading:"Percentages depend on the property",text:["A percentage does not have one universal reference.","width percentages usually relate to a containing block, transforms can relate to the transformed element itself, and line-height percentages relate to font size. Converting 50% to pixels without knowing the property and containing geometry is therefore not meaningful."]},
{heading:"Viewport units",text:["vw and vh are based on viewport dimensions, but mobile browsers introduced complications because browser chrome changes the visible area.","svh, lvh and dvh distinguish small, large and dynamic viewport sizes in modern CSS. Use viewport units deliberately for full-screen layouts and test keyboard/browser-toolbar behavior on real mobile devices."]},
{heading:"Physical units",text:["CSS also defines in, cm, mm, pt and pc, but on screens these are generally anchored to the CSS reference pixel rather than guaranteed physical measurements.","They become more useful in print styles where output dimensions matter. Do not assume 1cm in CSS will measure exactly one physical centimeter on every monitor."]},
{heading:"Fluid calculations with calc and clamp",text:["Modern CSS often avoids converting everything to one unit.","calc() can combine compatible values such as rem plus vw, while clamp() can enforce a minimum and maximum around a fluid preferred size. This is especially useful for responsive typography and spacing that should grow gradually instead of jumping only at breakpoints."]},
{heading:"Choosing the right unit",text:["Use units based on behavior: rem for user-scalable type systems, em for component-relative sizing, percentages for container-relative geometry, viewport units for viewport-relative effects and px for fine reference-pixel details where scaling is not required.","Test browser zoom, text enlargement and narrow screens; a mathematically correct conversion can still produce an inaccessible layout."]},
]},
"jwt-decoder":{title:"JWT Decoder",sections:[
{heading:"JWT structure",text:["A JSON Web Token commonly consists of three Base64url-encoded segments separated by periods: header, payload and signature.","The header describes metadata such as the signing algorithm, the payload contains claims, and the signature protects integrity. Decoding the first two segments is not the same as verifying the token."]},
{heading:"Base64url is not encryption",text:["JWT headers and payloads in a signed JWS are usually readable by anyone who obtains the token.","Base64url changes binary data into URL-safe text; it provides no confidentiality. Do not put passwords, private keys or unnecessary sensitive personal information into claims merely because the token looks scrambled."]},
{heading:"Signature verification",text:["Trust requires verifying the signature with the correct key and restricting accepted algorithms.","A decoder that displays claims without a key can help inspect a token, but it cannot prove who issued it or whether it was modified. Production libraries should reject unexpected algorithms and handle key rotation through trusted configuration or JWKS."]},
{heading:"Registered claims",text:["Common claims include iss for issuer, aud for audience, sub for subject, exp for expiration, nbf for not-before and iat for issued-at.","Validation must check the claims relevant to the application. A correctly signed token intended for a different audience or issuer should not automatically be accepted."]},
{heading:"Expiration and clock skew",text:["exp and nbf are NumericDate timestamps.","Servers can have small clock differences, so libraries may allow limited clock skew, but excessive tolerance weakens expiration controls. Long-lived bearer tokens increase exposure if stolen; short access-token lifetimes paired with a controlled refresh mechanism can reduce that window."]},
{heading:"JWT versus sessions",text:["JWTs are useful in distributed architectures but are not automatically better than server-side sessions. Revocation can be harder because a valid self-contained token may remain usable until expiration.","Session IDs can be opaque and centrally invalidated. Choose the model based on trust boundaries, scaling, revocation and operational needs rather than fashion."]},
{heading:"Safe debugging",text:["When decoding a real token, assume it may contain credentials or personal data. Avoid pasting production bearer tokens into untrusted websites.","For local debugging, redact the signature or use a locally running tool when possible. If a token has been exposed publicly, rotate or revoke the associated credential rather than relying on the fact that the token will eventually expire."]},
]},
"box-shadow-generator":{title:"Box Shadow Generator",sections:[
{heading:"The box-shadow syntax",text:["CSS box-shadow accepts horizontal offset, vertical offset, blur radius, spread radius and color, with an optional inset keyword.","Positive horizontal offset moves the shadow right and positive vertical offset moves it down. Blur softens the edge, while spread expands or contracts the shadow’s base shape before blurring."]},
{heading:"Blur and spread are different",text:["Blur controls softness, not physical distance from the element. Spread changes the size of the shadow region.","A subtle elevation effect often uses a small offset, moderate blur and low-opacity color rather than a large dark blur. Negative spread can keep a broad blur from making the component look oversized."]},
{heading:"Multiple shadows",text:["Comma-separated shadows are painted in layers and can create more natural depth than one heavy shadow.","Designers may combine a tight darker contact shadow with a broader faint ambient shadow. Multiple shadows are also useful for rings or decorative effects, but excessive layers can increase paint cost on large animated interfaces."]},
{heading:"Inset shadows",text:["inset changes the shadow from an outer elevation cue to an inner shadow, useful for pressed controls, wells or recessed surfaces.","It should be used carefully because strong inset shadows can reduce text contrast and make controls look disabled. The same offset, blur, spread and color concepts still apply."]},
{heading:"Color and dark mode",text:["Pure black at high opacity often looks harsh.","Shadow color can be derived from the surrounding theme, and dark interfaces may need lighter borders or carefully tuned shadows because dark-on-dark shadows disappear. Evaluate shadows on the actual background instead of copying one value across light and dark themes."]},
{heading:"Performance and animation",text:["Static box shadows are usually inexpensive at normal component sizes, but very large blur radii across many elements can increase painting work.","Animating box-shadow itself may be more expensive than animating transform or opacity. For interactive elevation, test performance on lower-powered devices and consider pseudo-elements whose opacity changes."]},
{heading:"Using generated values",text:["Generated CSS is a visual starting point, not a universal elevation system. Compare cards, menus, dialogs and buttons together so stronger shadows correspond to meaningful hierarchy.","Check focus outlines separately; a decorative shadow must not replace a visible keyboard focus indicator. Test clipped parents because overflow:hidden can cut off outer shadows."]},
]},
"word-counter":{title:"Word Counter",sections:[
{heading:"What counts as a word",text:["Word counting sounds simple until punctuation, hyphenation, apostrophes, numbers, emoji and non-Latin scripts appear.","A basic whitespace split may count “state-of-the-art” as one token and fail on languages that do not separate words with spaces. Different editors and publishing platforms can therefore report slightly different totals for the same text."]},
{heading:"Characters and spaces",text:["Character count can include or exclude whitespace depending on the use case.","Social platforms, SMS limits, metadata fields and database columns may define length differently. Unicode also complicates visible character counting: one user-perceived grapheme can consist of multiple code points, such as an accented letter built from a base character and combining mark."]},
{heading:"Reading time",text:["Estimated reading time usually divides word count by an assumed reading speed, often around a few hundred words per minute.","Real speed varies with language, technical complexity, formatting and reader familiarity. Code, equations and dense instructions take longer than conversational prose even when the raw word count is identical."]},
{heading:"Sentence and paragraph metrics",text:["Sentence counts typically rely on punctuation heuristics and can be confused by abbreviations, decimals or headings.","Paragraph counts depend on line-break conventions. These metrics are still useful for editing when interpreted as approximations: a wall of long paragraphs may be harder to scan even if the overall article length is appropriate."]},
{heading:"SEO and content quality",text:["A target word count does not guarantee useful content or search performance.","Repeating generic phrases to reach a number can make a page less helpful. Use word count to enforce editorial constraints or compare drafts, then evaluate whether the text answers the reader’s actual questions with specific information, examples and clear structure."]},
{heading:"Academic and professional limits",text:["Assignments, abstracts, grant applications and submissions may specify exactly what is included in a word limit.","References, footnotes, captions and tables may be treated differently by each institution. When compliance matters, use the counting method required by the destination rather than assuming a general-purpose counter will match it."]},
{heading:"Privacy and local processing",text:["Text pasted into a counter may contain unpublished, confidential or personal information.","A browser tool that performs counting locally can reduce exposure compared with sending text to a server, but users should verify the implementation and privacy policy. For sensitive documents, prefer trusted local software and avoid retaining pasted content unnecessarily."]},
]},
"budget-planner-calculator":{title:"Budget Planner Calculator",sections:[
{heading:"Start with cash flow",text:["A budget begins with after-tax income that is actually available to spend, not gross salary.","Include regular wages and, where appropriate, conservative estimates for variable income. Then separate essential obligations, flexible spending, debt payments, savings and irregular expenses so the plan reflects where cash must go each month."]},
{heading:"Fixed, variable and irregular expenses",text:["Rent, loan payments and subscriptions are relatively fixed; groceries, utilities and fuel vary; annual insurance, repairs and gifts are irregular but predictable.","Dividing annual or quarterly costs into monthly sinking-fund contributions prevents them from appearing as emergencies when the bill arrives."]},
{heading:"Needs, wants and goals",text:["Frameworks such as 50/30/20 can provide a starting structure, but local housing costs, family obligations and debt can make a fixed percentage unrealistic.","The useful question is whether essential needs are covered, discretionary spending fits available cash, and meaningful progress is being made toward emergency savings, debt reduction and long-term goals."]},
{heading:"Budgeting with variable income",text:["Freelancers and commission workers should avoid building recurring obligations around their best month.","One approach is to budget from a conservative baseline, keep a buffer in the business or checking account, and assign surplus months to taxes, sinking funds and goals. Separate gross business receipts from personal spendable income."]},
{heading:"Debt and interest",text:["Minimum debt payments belong in the required budget, but a payoff plan may allocate additional cash to high-interest balances.","Interest rates affect how quickly debt grows, so reducing an expensive balance can produce a more certain financial benefit than leaving the same money in low-yield cash beyond the emergency reserve."]},
{heading:"Tracking versus planning",text:["A budget is forward-looking, while expense tracking records what already happened. Both are useful.","Compare actual spending with planned categories at least monthly and adjust categories that are consistently unrealistic. The goal is not to punish every variance but to make deliberate tradeoffs before the money is gone."]},
{heading:"Keeping the plan resilient",text:["Leave room for small surprises rather than assigning every last unit of income.","Revisit the plan after a move, raise, job loss, new child, debt payoff or major insurance change. A sustainable budget should support daily life as well as future goals; an extremely restrictive plan that is repeatedly abandoned is less useful than a realistic one that can be maintained."]},
]},
"grid-generator":{title:"CSS Grid Generator",sections:[
{heading:"Grid container and tracks",text:["display:grid creates a two-dimensional layout system whose columns and rows are defined as tracks.","grid-template-columns and grid-template-rows can use fixed lengths, percentages, fr units, minmax() and repeat(). Unlike Flexbox, Grid can align items across both rows and columns, making it well suited to page layouts and structured card collections."]},
{heading:"Understanding the fr unit",text:["fr distributes leftover space after fixed sizes, gaps and intrinsic constraints are considered.","grid-template-columns:1fr 2fr gives the second flexible track twice the share of remaining space, not necessarily twice the final pixel width if content imposes minimum sizes. minmax(0,1fr) is sometimes useful when long content would otherwise force overflow."]},
{heading:"Explicit and implicit grids",text:["Tracks declared in grid-template-* form the explicit grid.","When items are placed outside it or auto-placement needs more tracks, the browser creates an implicit grid controlled by grid-auto-rows or grid-auto-columns. Unexpected extra columns or rows often come from implicit placement rather than a failure of the declared template."]},
{heading:"Placement and grid lines",text:["Items can be placed using numbered lines, named lines or grid-template-areas. span lets an item cover multiple tracks.","Named areas can make application layouts easier to read, while numeric lines are compact for repeated components. Avoid visual reordering that creates a keyboard or screen-reader sequence different from the DOM order."]},
{heading:"Responsive grids",text:["repeat(auto-fit,minmax(...)) can create responsive card grids without many media queries.","auto-fit collapses unused tracks, while auto-fill preserves potential track slots. The minimum value should reflect the component’s real content needs; an arbitrary small minimum may create cramped cards before the layout wraps."]},
{heading:"Alignment and gaps",text:["gap controls spacing between tracks.","justify-items and align-items position content inside grid areas, while justify-content and align-content position the grid as a whole when the container has extra space. place-items and place-content are convenient shorthands, but knowing which level is being aligned prevents confusing results."]},
{heading:"Grid versus Flexbox",text:["Use Grid when relationships between rows and columns are central; use Flexbox when content primarily flows along one axis. They are complementary.","A dashboard might use Grid for major panels and Flexbox for controls inside each panel. Test long text, dynamic item counts and zoom because intrinsic sizing can reveal layout problems hidden by placeholder content."]},
]},
"bandwidth-calculator":{title:"Bandwidth Calculator",sections:[
{heading:"Bits, bytes and transfer rates",text:["Network bandwidth is usually advertised in bits per second, while file sizes are commonly shown in bytes.","Eight bits equal one byte, so a 100 MB file contains roughly 800 megabits before accounting for decimal versus binary prefixes. Confusing Mbps with MB/s creates an eightfold error in estimated transfer time."]},
{heading:"Transfer-time formula",text:["Ideal transfer time equals data size divided by throughput after both values are converted to compatible units.","A 1 gigabyte file over a sustained 100 megabit-per-second path takes more than a minute even before protocol overhead. The word sustained matters: the connection’s headline link rate is an upper bound, not a guarantee of application throughput."]},
{heading:"Protocol and encoding overhead",text:["Ethernet, IP, TCP/TLS and application protocols add headers and control traffic. Retransmissions consume additional capacity when packets are lost.","Some applications also expand data through encoding, while compression can reduce transfer size for compressible content. Real throughput should therefore be measured at the layer that matters to the user."]},
{heading:"Latency versus bandwidth",text:["Bandwidth measures how much data can move per unit time; latency measures how long a request or packet takes to travel.","A high-bandwidth connection can still feel slow for interactive applications if latency is high. Small API calls and gaming often care more about latency and jitter, while large backups and video distribution depend heavily on sustained throughput."]},
{heading:"Shared links and concurrency",text:["Home, office and cloud links are shared by multiple flows. Ten simultaneous downloads do not each receive the full line rate indefinitely.","Wi-Fi clients also share airtime, and radio interference can reduce usable capacity. Capacity planning should model concurrent users, peak periods and expected per-user demand rather than multiplying one speed-test result blindly."]},
{heading:"Streaming and headroom",text:["Video and live streaming need throughput above the encoded media bitrate because of protocol overhead and short-term variation.","Buffering provides some protection, but live applications have less room to absorb stalls. Keeping headroom above average demand improves resilience during bursts and avoids running a link continuously at saturation."]},
{heading:"Planning with realistic measurements",text:["Use recent sustained measurements from the actual path, not only the ISP plan. Test wired versus Wi-Fi, peak hours and relevant geographic destinations.","For business systems, monitor percentile utilization, packet loss and latency alongside Mbps. A bandwidth calculator provides a capacity estimate; it cannot model every routing, radio or server bottleneck between endpoints."]},
]},
"css-gradient-generator":{title:"CSS Gradient Generator",sections:[
{heading:"Linear gradients",text:["linear-gradient() creates a generated image that transitions between color stops along a line. Direction can be expressed with keywords such as to right or with angles.","Zero degrees points upward in CSS gradient geometry, and increasing angles rotate clockwise. Multiple stops allow bands, highlights and complex transitions rather than a simple two-color fade."]},
{heading:"Radial and conic gradients",text:["radial-gradient() expands colors outward from a center using circle or ellipse geometry.","conic-gradient() rotates color stops around a center, making it useful for color wheels, pie-like visuals and angular effects. Each gradient type has different positioning and sizing controls, so converting one type to another is not just a syntax change."]},
{heading:"Color stops and hard edges",text:["A stop can specify a color and position. Giving adjacent colors the same or nearby positions can create a hard edge instead of a smooth blend.","Repeating gradients repeat a pattern across the element and can create stripes or grids without image files. Keep the CSS understandable when decorative patterns become complex."]},
{heading:"Color interpolation",text:["The visual midpoint between two colors depends on the color space used for interpolation and browser support.","Some transitions can look muddy when interpolated in traditional sRGB. Modern CSS Color features can provide more perceptually useful interpolation options, but compatibility should be checked before relying on newer syntax in production."]},
{heading:"Layering gradients",text:["Multiple background images can be comma-separated, allowing gradients to layer over each other or over a URL image.","Transparency in upper layers reveals lower layers. This can create overlays, vignettes and texture effects without extra DOM elements, but many large gradient layers can increase painting complexity."]},
{heading:"Accessibility and text",text:["A decorative gradient behind text must maintain sufficient contrast across the entire region where the text can appear. A color pair that passes contrast at one end may fail in the middle.","Consider a solid overlay, text container background or alternative theme for users who need stronger contrast. Gradients should not be the only way to communicate status."]},
{heading:"Production use",text:["Generated gradient CSS should be tested at the actual component dimensions because stop positions can look different on a wide banner and a small button.","Check browser support for advanced syntax and provide a solid-color fallback where necessary. Prefer reusable design tokens for brand colors so gradients remain consistent when the palette changes."]},
]},
"sql-formatter":{title:"SQL Formatter",sections:[
{heading:"Formatting versus changing SQL",text:["A SQL formatter should change presentation—indentation, line breaks, keyword casing and spacing—without changing query semantics.","It is not a query optimizer and should not be assumed to validate business logic. Always review formatted output before replacing production SQL, especially when the tool also attempts parsing or dialect-specific rewrites."]},
{heading:"Readable SELECT structure",text:["Long SELECT lists become easier to review when columns are placed consistently and aliases are obvious.","FROM and JOIN clauses should expose table relationships, while WHERE predicates can be broken across lines to reveal AND/OR grouping. Parentheses remain important because indentation alone does not change operator precedence."]},
{heading:"JOIN readability",text:["Explicit JOIN ... ON syntax is generally clearer than hiding relationships in a WHERE clause.","Formatting should make each join condition visually associated with its table. This helps reviewers spot accidental Cartesian products, incomplete composite-key joins and filters that turn an intended LEFT JOIN into inner-join behavior."]},
{heading:"CTEs and subqueries",text:["Common table expressions can make multi-stage transformations easier to understand when each CTE has one clear purpose.","Formatting nested subqueries with consistent indentation is essential when CTEs are unavailable or inappropriate. Readability does not guarantee performance; some database engines optimize equivalent forms differently depending on statistics and version."]},
{heading:"Dialect differences",text:["SQL is a family of dialects.","PostgreSQL, SQL Server, MySQL, SQLite, Oracle, BigQuery and others differ in quoting, functions, LIMIT/TOP/FETCH syntax, procedural extensions and data types. A formatter configured for the wrong dialect may misinterpret valid syntax or produce awkward output."]},
{heading:"Comments and generated SQL",text:["Preserve comments because they may explain intentional workarounds, hints or operational constraints.","Generated SQL from ORMs can be huge and may use parameter placeholders that look unfamiliar. Formatting it is useful for debugging, but manually editing generated output is usually not the durable fix; change the source query or ORM configuration instead."]},
{heading:"Safe workflow",text:["Format a copy, inspect the diff and run the query in an appropriate non-production environment when possible.","Never paste SQL containing credentials, customer data or confidential literals into an untrusted online service. For team consistency, use the same formatter configuration in editors, CI and pre-commit hooks so style does not oscillate between contributors."]},
]},
"html-entity-ref":{title:"HTML Entity Reference",sections:[
{heading:"Why HTML entities exist",text:["HTML uses characters such as <, >, & and quotes as part of markup syntax.","Character references let those characters appear as text without being interpreted as markup in contexts where escaping is required. Named references such as &amp; coexist with numeric references such as &#38; and hexadecimal references such as &#x26;."]},
{heading:"Named versus numeric references",text:["Named entities are readable for familiar characters, but HTML defines many names and not every XML parser recognizes the same set.","Numeric references identify Unicode code points and are more general. In HTML documents, use the normal literal Unicode character when it is safe and readable; entities are not required for every non-ASCII symbol when UTF-8 is used."]},
{heading:"Escaping text content",text:["In normal HTML text, ampersand and less-than need particular care because they can begin character references or tags.","Greater-than is usually safe but is often escaped in generated contexts for consistency. Correct escaping should be performed by the templating or DOM API rather than by repeatedly applying manual string replacements."]},
{heading:"Attributes and quotes",text:["Attribute values introduce an additional delimiter.","If a value is enclosed in double quotes, a literal double quote must be encoded or otherwise safely handled; the same principle applies to single-quoted attributes. Modern frameworks usually escape interpolated attribute values automatically, but bypass APIs such as dangerouslySetInnerHTML require much greater care."]},
{heading:"Entities are not a universal security filter",text:["HTML escaping helps prevent markup injection in an HTML context, but security depends on context. JavaScript strings, CSS, URLs and HTML attributes have different parsing rules.","A value safely escaped for element text is not automatically safe when inserted into a script or URL. Prefer context-aware framework APIs and sanitization for untrusted rich HTML."]},
{heading:"Unicode and encoding",text:["Entities ultimately represent characters, so the document’s character encoding still matters. UTF-8 is the normal choice for modern web pages and can represent the full Unicode repertoire.","Mojibake usually indicates an encoding mismatch rather than a missing HTML entity. Fix the byte/charset pipeline instead of converting every character to an entity."]},
{heading:"Using the reference table",text:["When looking up an entity, confirm the displayed character, Unicode code point and exact syntax including the semicolon.","Some historical named references have parsing quirks when the semicolon is omitted; always include it in authored markup. For programmatic output, rely on a standards-compliant encoder rather than maintaining a partial hand-written replacement list."]},
]},
}
export function CalculatorBatch51DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mx-auto max-w-5xl px-4 py-10"><div className="rounded-2xl border border-gray-200 bg-white p-6 md:p-8"><h2 className="text-2xl md:text-3xl font-bold text-gray-900">{g.title}: Detailed Guide</h2><p className="mt-3 text-gray-700 leading-7">This guide explains the concepts, mechanics, limitations and practical interpretation specific to this tool.</p><div className="mt-8 space-y-8">{g.sections.map((s,i)=><article key={i}><h3 className="text-xl font-semibold text-gray-900">{s.heading}</h3>{s.text.map((p,j)=><p key={j} className="mt-3 text-gray-700 leading-7">{p}</p>)}</article>)}</div></div></section>}